var pipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region))
    .Append(mlContext.Transforms.Concatenate("Features", nameof(CustomerData.Age), nameof(CustomerData.Income),
        "RegionEncoded", nameof(CustomerData.PurchaseHistory)))
    .Append(mlContext.Transforms.NormalizeMinMax("Features"))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
        labelColumnName: nameof(CustomerData.Churned), featureColumnName: "Features"));

// Use train/test split when enough data is available; otherwise train and evaluate on full dataset
var rowCount = (int)mlContext.Data.CreateEnumerable<CustomerData>(dataView, reuseRowObject: false).LongCount();
ITransformer model;
if (rowCount >= 20)
{
    var split = mlContext.Data.TrainTestSplit(dataView, testFraction: 0.2);
    model = pipeline.Fit(split.TrainSet);
    var metrics = mlContext.BinaryClassification.Evaluate(
        model.Transform(split.TestSet), labelColumnName: nameof(CustomerData.Churned));
    Console.WriteLine($"Model trained — AUC: {metrics.AreaUnderRocCurve:F4}, Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");
}
else
{
    model = pipeline.Fit(dataView);
    var metrics = mlContext.BinaryClassification.Evaluate(
        model.Transform(dataView), labelColumnName: nameof(CustomerData.Churned));
    Console.WriteLine($"Model trained (small dataset, {rowCount} rows — add more data for reliable metrics)");
    Console.WriteLine($"  Training-set AUC: {metrics.AreaUnderRocCurve:F4}, Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");
}

